    private void init() throws IOException {
        File f = new File(file);
        RandomAccessFileReader in = new RandomAccessFileReader(f);
        SimpleDateFormat dateformat = new SimpleDateFormat(DATE_FORMAT);
        Pattern idp = Pattern.compile("\\[myid:(\\d+)\\]");
        long lastFp = in.getPosition();
        String line = in.readLine();
        Matcher m = null;
        // if we have read data from the file, and it matches the timep pattern
        if ((line != null) && (m = timep.matcher(line)).lookingAt()) {
            starttime = timestampFromText(dateformat, m.group(1));
        } else {
            throw new IOException("Invalid log format. First line doesn't start with time");
        }
        /*
	  Count number of log entries. Any line starting with a timestamp counts as an entry
	*/

        String lastentry = line;

        try {
            while (line != null) {
                m = timep.matcher(line);

                if (m.lookingAt()) {
                    if (size % skipN == 0) {
                        long time = timestampFromText(dateformat, m.group(1));
                        skiplist.addMark(time, lastFp, size);
                    }

                    size++;
                    lastentry = line;
                } 

                if (serverid == 0 && (m = idp.matcher(line)).find()) {
                    serverid = Integer.valueOf(m.group(1));
                }

                lastFp = in.getPosition();
                line = in.readLine();
            }
        } catch (EOFException eof) {
        // ignore, simply end of file, though really (line!=null) should have caught this
        } finally {
            in.close();
        }

        m = timep.matcher(lastentry);

        if (m.lookingAt()) {
            endtime = timestampFromText(dateformat, m.group(1));
        } else {
            throw new IOException("Invalid log format. Last line doesn't start with time");
        }
    }

void _processDo(int option) throws IOException{
    if (debugoptions) {
        System.err.println("RECEIVED DO: " + TelnetOption.getOption(option));
    }

    if (__notifhand != null) {
        __notifhand.receivedNegotiation(TelnetNotificationHandler.RECEIVED_DO, option);
    }

    boolean acceptNewState = false;
    /* open TelnetOptionHandler functionality (start)*/

    if (optionHandlers[option] == null) {/* open TelnetOptionHandler functionality (end)*//* TERMINAL-TYPE option (start)*/
        if (option == TERMINAL_TYPE && ((terminalType != null) && (terminalType.length() > 0))) {
            acceptNewState = true;
        }
    }/* open TelnetOptionHandler functionality (end)*/else {
        acceptNewState = optionHandlers[option].getAcceptLocal();
    }

    if (_willResponse[option] > 0) {
        _willResponse[option]--; 

        if (_willResponse[option] > 0 && _stateIsWill(option)) {
            _willResponse[option]--; 
        }
    }

    if (_willResponse[option] == 0) {
        if (_requestedWont(option)) {
            switch (option) {
                default:
                    break;
            }

            if (acceptNewState) {
                _setWantWill(option);
                _sendWill(option);
            } else {
                _willResponse[option]++; 
                _sendWont(option);
            }
        } else {// Other end has acknowledged option.

            switch (option) {
                default:
                    break;
            }
        }
    }

    _setWill(option);
}

@Override
public void drain() {
    if (getAndIncrement() != 0) {
        return;
    }

    int missed = 1;
    InnerQueuedSubscriber<R> inner = current;
    Subscriber<? super R> a = downstream;
    ErrorMode em = errorMode;

    for (;;) {
        long r = requested.get();
        long e = 0L;

        if (inner == null) {
            if (em != ErrorMode.END) {
                Throwable ex = errors.get();
                if (ex != null) {
                    cancelAll();
                    errors.tryTerminateConsumer(downstream);
                    return;
                }
            }

            boolean outerDone = done;
            inner = subscribers.poll();

            if (outerDone && inner == null) {
                errors.tryTerminateConsumer(downstream);
                return;
            }
            if (inner != null) {
                current = inner;
            }
        }

        boolean continueNextSource = false;

        if (inner != null) {
            SimpleQueue<R> q = inner.queue();

            if (q != null) {
                while (e != r) {
                    if (cancelled) {
                        cancelAll();
                        return;
                    }
                    if (em == ErrorMode.IMMEDIATE) {
                        Throwable ex = errors.get();
                        if (ex != null) {
                            current = null;
                            inner.cancel();
                            cancelAll();
                            errors.tryTerminateConsumer(downstream);
                            return;
                        }
                    }

                    boolean d = inner.isDone();
                    R v;
                    try {
                        v = q.poll();
                    } catch (Throwable ex) {
                        Exceptions.throwIfFatal(ex);
                        current = null;
                        inner.cancel();
                        cancelAll();
                        a.onError(ex);
                        return;
                    }

                    boolean empty = v == null;
                    if (d && empty) {
                        inner = null;
                        current = null;
                        upstream.request(1);
                        continueNextSource = true;
                        break;
                    }
                    if (empty) {
                        break;
                    }
                    a.onNext(v);
                    e++;
                    inner.request(1L);
                }

                if (e == r) {
                    if (cancelled) {
                        cancelAll();
                        return;
                    }
                    if (em == ErrorMode.IMMEDIATE) {
                        Throwable ex = errors.get();
                        if (ex != null) {
                            current = null;
                            inner.cancel();
                            cancelAll();
                            errors.tryTerminateConsumer(downstream);
                            return;
                        }
                    }

                    boolean d = inner.isDone();
                    boolean empty = q.isEmpty();
                    if (d && empty) {
                        inner = null;
                        current = null;
                        upstream.request(1);
                        continueNextSource = true;
                    }
                }
            }
        }
        if (e != 0L && r != Long.MAX_VALUE) {
            requested.addAndGet(-e);
        }
        if (!continueNextSource) { 
            missed = addAndGet(-missed);

            if (missed == 0) {
                break;
            }
        } 
    }
}

private static Object process(final RedisInputStream is) {
    final byte b = is.readByte();
    // System.out.println("BYTE: " + (char) b);
    switch (b) {
        case PLUS_BYTE:
            return is.readLineBytes();
        case DOLLAR_BYTE:
        case EQUAL_BYTE:
            return processBulkReply(is);
        case ASTERISK_BYTE:
            return processMultiBulkReply(is);
        case UNDERSCORE_BYTE:
            return is.readNullCrLf();
        case HASH_BYTE:
            return is.readBooleanCrLf();
        case COLON_BYTE:
            return is.readLongCrLf();
        case COMMA_BYTE:
            return is.readDoubleCrLf();
        case LEFT_BRACE_BYTE:
            return is.readBigIntegerCrLf();
        case PERCENT_BYTE: // TODO: currently just to start working with HELLO

            return processMapKeyValueReply(is);
        case TILDE_BYTE: // TODO:

            return processMultiBulkReply(is);
        case GREATER_THAN_BYTE:
            return processMultiBulkReply(is);
        case MINUS_BYTE:
            processError(is);
            return null;
        // TODO: Blob error '!'
        default:
            throw new JedisConnectionException("Unknown reply: " + (char) b);
    }
}

